var ts = SugarCube.State.variables.game_state.time_state;
var npcLoc = setup.getNpcLocation('npc_smokey');
return JSON.stringify({
    time: ts.current_day + ' ' + ts.current_hour + ':' + (ts.current_minute < 10 ? '0' + ts.current_minute : ts.current_minute),
    npcLoc: npcLoc,
    locKitchenUuid: (setup.locations || {})['loc_kitchen'] && setup.locations['loc_kitchen'].id,
    npcSchedules: setup.npcSchedules
}, null, 2);

