SugarCube.State.variables.game_state.time_state.current_minute = 0;
SugarCube.State.variables.game_state.random_cooldowns = {};
var s = SugarCube.setup;
var ts = SugarCube.State.variables.game_state.time_state;
return JSON.stringify({
    timeNow: ts.current_day + ' ' + ts.current_hour + ':' + (ts.current_minute < 10 ? '0' + ts.current_minute : ts.current_minute),
    npcLocAt1100: s.getNpcLocation('npc_smokey'),
    isCurrentTimeSlot_in_window: s.isCurrentTimeSlot('06:00', '10:00')
}, null, 2);

